package template

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/santhosh-tekuri/jsonschema/v5"
	"gopkg.in/yaml.v3"
)

// StdinValuesPath is the sentinel a caller may pass in the values-file list
// to signal "read a single values document from this reader". It mirrors the
// `-f -` idiom used by helm, kubectl, and curl.
const StdinValuesPath = "-"

// Resolve produces the final value map by layering, in order:
//
//	defaults declared in spec.parameters.properties[*].default
//	--values files (in supplied order; "-" reads one doc from stdin)
//	--set flags (string values, coerced to declared JSON Schema types)
//	prompts for required parameters still missing (when prompter != nil)
//
// stdin is consumed at most once across the files list; passing "-" twice is
// an error. The merged map is then validated against the JSON Schema in
// spec.parameters. Finally, every entry in spec.values is rendered as a Go
// text/template (with sprig) against the merged map and added under its key.
// A spec.values key that collides with a parameter name is rejected.
func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveLayered is Resolve with an extra base layer that sits between the
// spec.parameters defaults and the --values files. Callers use it to seed
// values from an earlier resolution (e.g. a committed scaffold record) so
// they take effect without re-prompting but still yield to explicit
// --values / --set input.
func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Base: base, Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveOptions is the full input to value resolution. The zero value is
// a bare resolve: schema defaults, then nothing else. Each field names one
// layer or instrument, in the order resolution applies them — Base under
// Files under Sets, Facts informing prefill and prompts, Prompter and
// Notes as the interactive and diagnostic surfaces.
type ResolveOptions struct {
	// Base sits between the schema defaults and the values files. Callers
	// seed it from an earlier resolution (e.g. a committed scaffold record)
	// so it takes effect without re-prompting but yields to explicit input.
	Base map[string]any

	// Facts is the workspace's declared wiring. It changes resolution in
	// two deliberate ways, both overridable with --set/--values:
	//
	//   - prefill: a required parameter with exactly one workspace
	//     candidate resolves to it without prompting, behaving like an
	//     optional parameter with a workspace-derived default. Each
	//     prefill is noted on Notes so the value never lands invisibly.
	//   - prompt suggestions: a parameter with several candidates prompts
	//     with them as a pick list; the prompter's confirmation is the
	//     value.
	//
	// A nil facts index resolves exactly as ResolveLayered always has.
	Facts *WorkspaceFacts

	// Files are --values files in supplied order; "-" reads one document
	// from Stdin (consumed at most once).
	Files []string
	Stdin io.Reader

	// Sets are --set flag values, applied last of the input layers.
	Sets map[string]any

	// Prompter resolves required parameters still missing after every
	// input layer; nil turns a miss into the missing-parameter error.
	Prompter Prompter

	// Notes receives one line per prefilled value — typically stderr. Nil
	// silences the notes, not the prefill.
	Notes io.Writer
}

// ResolveWith is the resolution all of Resolve, ResolveLayered, and the
// create flows share: the input layers in declaration order, prefill and
// prompts for what they leave open, then schema validation and derived
// values.
func ResolveWith(t *Template, opts ResolveOptions) (map[string]any, error) {
	fields := t.Fields()
	byName := indexFields(fields)
	out := map[string]any{}

	applyDefaultValues(fields, out)
	for k, v := range opts.Base {
		out[k] = coerceKnownFieldValue(k, v, byName)
	}
	if err := applyValuesFiles(opts.Files, opts.Stdin, out, byName); err != nil {
		return nil, err
	}
	applySetValues(opts.Sets, out, byName)
	prefill, _ := candidatesByArity(fields, out, opts.Facts)
	applyPrefill(fields, out, prefill, opts.Notes)
	if err := promptForMissingRequired(fields, out, opts.Facts, opts.Prompter); err != nil {
		return nil, err
	}
	if err := validateSchema(t.Spec.Parameters, out); err != nil {
		return nil, fmt.Errorf("parameter validation: %w", err)
	}
	if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
		return nil, err
	}

	return out, nil
}

// candidatesByArity computes every open required parameter's workspace
// candidates once and splits them by what they imply: exactly one
// candidate is a prefill pick, several are prompt suggestions. Fields
// already valued — by default, base, --values, or --set — have neither.
// The single computation keeps prefill and prompts reading one snapshot,
// so the two paths can never disagree about what the workspace offers.
func candidatesByArity(fields []FieldSpec, values map[string]any, facts *WorkspaceFacts) (prefill, suggestions map[string][]string) {
	open := make([]FieldSpec, 0, len(fields))
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		open = append(open, f)
	}
	prefill = map[string][]string{}
	suggestions = map[string][]string{}
	for name, candidates := range Suggest(open, facts, values) {
		if len(candidates) == 1 {
			prefill[name] = candidates
		} else {
			suggestions[name] = candidates
		}
	}
	return prefill, suggestions
}

// applyPrefill resolves the single-candidate picks candidatesByArity
// separated, chaining as it goes: a prefilled topic constrains contract's
// candidates to that topic's contract, so a workspace with one topic
// resolves the whole wiring without a prompt. Each prefill is noted so
// the value never lands invisibly.
func applyPrefill(fields []FieldSpec, values map[string]any, prefill map[string][]string, notes io.Writer) {
	for _, f := range fields {
		candidates, ok := prefill[f.Name]
		if !ok {
			continue
		}
		if v, valued := values[f.Name]; valued && !isEmpty(v) {
			continue
		}
		values[f.Name] = candidates[0]
		if notes != nil {
			fmt.Fprintf(notes, "%s: %s (from workspace; override with --set %s=<value>)\n", f.Name, candidates[0], f.Name)
		}
	}
}

func applyDefaultValues(fields []FieldSpec, values map[string]any) {
	for _, f := range fields {
		if f.Default != nil {
			values[f.Name] = f.Default
		}
	}
}

func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
	stdinUsed := false
	for _, path := range files {
		if path == StdinValuesPath {
			if stdinUsed {
				return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
			}
			if stdin == nil {
				return fmt.Errorf("--values - specified but no stdin reader provided")
			}
			data, err := io.ReadAll(stdin)
			if err != nil {
				return fmt.Errorf("read values from stdin: %w", err)
			}
			if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
				return err
			}
			stdinUsed = true
			continue
		}
		if err := mergeValuesFile(path, values, byName); err != nil {
			return err
		}
	}
	return nil
}

func applySetValues(sets map[string]any, values map[string]any, byName map[string]FieldSpec) {
	for k, v := range sets {
		values[k] = coerceKnownFieldValue(k, v, byName)
	}
}

func promptForMissingRequired(fields []FieldSpec, values map[string]any, facts *WorkspaceFacts, prompter Prompter) error {
	missing := missingRequired(fields, values)
	if len(missing) == 0 {
		return nil
	}
	suggestions := suggestMissing(missing, facts, values)
	if prompter == nil {
		return missingRequiredError(missing, suggestions)
	}
	for _, f := range missing {
		f.Suggestions = suggestions[f.Name]
		ans, _, err := prompter.Prompt(f)
		if err != nil {
			return err
		}
		if isEmpty(ans) {
			return fmt.Errorf("required parameter %q has no value", f.Name)
		}
		values[f.Name] = ans
		// Re-derive after every answer, picked or typed: the answered
		// parameter leaves the open set, and its value may constrain what
		// remains (a known topic narrows the contract candidates).
		// Deriving candidates is the prompt loop's invariant — never cache
		// a suggestion list across answers.
		suggestions = suggestMissing(missing, facts, values)
	}
	return nil
}

// suggestMissing derives candidates for the still-open fields from the
// current value map. It is the prompt loop's one derivation point —
// called before the first prompt and again after every answer — so a
// suggestion list never outlives the values it was derived from.
// Answered fields drop out of the open set; the map holds only what a
// prompt or the missing-parameter error can still act on.
func suggestMissing(missing []FieldSpec, facts *WorkspaceFacts, values map[string]any) map[string][]string {
	unresolved := make([]FieldSpec, 0, len(missing))
	for _, f := range missing {
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		unresolved = append(unresolved, f)
	}
	return Suggest(unresolved, facts, values)
}

// missingRequiredError reports unmet required parameters, appending one
// hint line per field the workspace has candidates for. The hints name
// what --set would accept so a CI failure documents the values the run
// could not ask for.
func missingRequiredError(missing []FieldSpec, suggestions map[string][]string) error {
	names := make([]string, 0, len(missing))
	for _, f := range missing {
		names = append(names, f.Name)
	}
	err := fmt.Sprintf("missing required parameter(s): %s", strings.Join(names, ", "))
	for _, f := range missing {
		if c := suggestions[f.Name]; len(c) > 0 {
			err += fmt.Sprintf("\nknown %s values in this workspace: %s", f.Name, strings.Join(c, ", "))
		}
	}
	return fmt.Errorf("%s", err)
}

func renderDerivedValues(derived map[string]string, values map[string]any, byName map[string]FieldSpec) error {
	for k, expr := range derived {
		if _, collides := byName[k]; collides {
			return fmt.Errorf("spec.values.%s collides with a parameter of the same name", k)
		}
		rendered, err := renderExpr(expr, values)
		if err != nil {
			return fmt.Errorf("spec.values.%s: %w", k, err)
		}
		values[k] = rendered
	}
	return nil
}

func mergeValuesFile(path string, into map[string]any, byName map[string]FieldSpec) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read values file %s: %w", path, err)
	}
	return mergeValuesBytes(data, path, into, byName)
}

func mergeValuesBytes(data []byte, source string, into map[string]any, byName map[string]FieldSpec) error {
	var fileVals map[string]any
	if err := yaml.Unmarshal(data, &fileVals); err != nil {
		return fmt.Errorf("parse values from %s: %w", source, err)
	}
	for k, v := range fileVals {
		into[k] = coerceKnownFieldValue(k, v, byName)
	}
	return nil
}

func coerceKnownFieldValue(name string, value any, byName map[string]FieldSpec) any {
	field, ok := byName[name]
	if !ok {
		return value
	}
	str, ok := value.(string)
	if !ok {
		return value
	}
	return coerce(str, field.Type)
}

func indexFields(fields []FieldSpec) map[string]FieldSpec {
	m := make(map[string]FieldSpec, len(fields))
	for _, f := range fields {
		m[f.Name] = f
	}
	return m
}

func missingRequired(fields []FieldSpec, values map[string]any) []FieldSpec {
	var missing []FieldSpec
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		missing = append(missing, f)
	}
	return missing
}

func validateSchema(schema map[string]any, values map[string]any) error {
	raw, err := json.Marshal(schema)
	if err != nil {
		return err
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("inline://params.json", bytes.NewReader(raw)); err != nil {
		return err
	}
	s, err := c.Compile("inline://params.json")
	if err != nil {
		return err
	}
	return s.Validate(values)
}

// compileExpr parses a Go text/template string with sprig helpers and
// missingkey=error, so an undefined value name is a loud failure rather than a
// silently empty string. Separate from renderExpr because spec.files rules are
// parsed at load time to reject a syntax error early, and only evaluated later
// once values exist.
func compileExpr(expr string) (*template.Template, error) {
	return template.New("expr").
		Funcs(sprig.TxtFuncMap()).
		Option("missingkey=error").
		Parse(expr)
}

// renderExpr renders a Go text/template string (with sprig) against the
// supplied data map. Used for spec.values entries and spec.files conditions.
func renderExpr(expr string, data map[string]any) (string, error) {
	tmpl, err := compileExpr(expr)
	if err != nil {
		return "", err
	}
	var sb strings.Builder
	if err := tmpl.Execute(&sb, data); err != nil {
		return "", err
	}
	return sb.String(), nil
}

// ParseSets converts ["key=value", ...] into a map. Values stay as strings;
// Resolve coerces them to the JSON Schema type when the key matches a known
// parameter.
func ParseSets(items []string) (map[string]any, error) {
	out := map[string]any{}
	for _, item := range items {
		i := strings.Index(item, "=")
		if i <= 0 {
			return nil, fmt.Errorf("invalid --set %q (expected key=value)", item)
		}
		out[item[:i]] = item[i+1:]
	}
	return out, nil
}

func isEmpty(v any) bool {
	switch t := v.(type) {
	case nil:
		return true
	case string:
		return t == ""
	default:
		return false
	}
}

import type { TemplateField } from '../api'

// The template-form controls shared by every create surface (the templates
// view, the flow view's create drawer): one schema parameter rendered as the
// matching input, and the label + control row it sits in.

// FormField renders one schema parameter as the matching input: a combobox
// for an enum, a checkbox for a boolean, a number input for integer/number,
// a text input otherwise. Pattern and required come straight from the schema.
export function FormField({
  field,
  value,
  onChange,
}: {
  field: TemplateField
  value: unknown
  onChange: (key: string, v: unknown) => void
}) {
  const set = (v: unknown) => onChange(field.name, v)

  let input: React.ReactNode
  if (field.type === 'boolean') {
    input = (
      <input
        type="checkbox"
        checked={Boolean(value)}
        onChange={(e) => set(e.target.checked)}
      />
    )
  } else if (field.enum && field.enum.length > 0) {
    input = (
      <select
        value={value === undefined ? '' : String(value)}
        onChange={(e) => set(e.target.value || undefined)}
      >
        <option value="">—</option>
        {field.enum.map((opt) => (
          <option key={String(opt)} value={String(opt)}>
            {String(opt)}
          </option>
        ))}
      </select>
    )
  } else if (field.suggestions && field.suggestions.length > 0) {
    // Workspace candidates ride a datalist: the input stays free text
    // (a scaffold may deliberately declare a new topic) while the known
    // values are one arrow-key away. A select would close the list; the
    // CLI prompt's pick-list-plus-freetext is the parity target.
    const listId = `suggestions-${field.name}`
    input = (
      <>
        <input
          type="text"
          value={value === undefined ? '' : String(value)}
          pattern={field.pattern || undefined}
          list={listId}
          onChange={(e) => set(e.target.value === '' ? undefined : e.target.value)}
        />
        <datalist id={listId}>
          {field.suggestions.map((s) => (
            <option key={s} value={s} />
          ))}
        </datalist>
      </>
    )
  } else if (field.type === 'integer' || field.type === 'number') {
    input = (
      <input
        type="number"
        value={value === undefined ? '' : String(value)}
        step={field.type === 'integer' ? 1 : 'any'}
        onChange={(e) => set(e.target.value === '' ? undefined : Number(e.target.value))}
      />
    )
  } else {
    input = (
      <input
        type="text"
        value={value === undefined ? '' : String(value)}
        pattern={field.pattern || undefined}
        onChange={(e) => set(e.target.value === '' ? undefined : e.target.value)}
      />
    )
  }

  return (
    <Field
      label={field.name}
      title={field.title}
      description={field.description}
      required={field.required}
      type={field.type}
    >
      {input}
    </Field>
  )
}

// Field is the label + control row every parameter renders through, with the
// same required marker `template show` prints.
export function Field({
  label,
  title,
  description,
  required,
  type,
  children,
}: {
  label: string
  title?: string
  description?: string
  required?: boolean
  type?: string
  children: React.ReactNode
}) {
  return (
    <label className="form-field">
      <span className="form-label">
        {required && <span className="req" aria-hidden>*</span>}
        {label}
        {title && <span className="form-label-title"> — {title}</span>}
        {type && <span className="form-type">[{type}]</span>}
      </span>
      {children}
      {description && <span className="form-desc">{description}</span>}
    </label>
  )
}

export function isEmpty(v: unknown): boolean {
  return v === undefined || v === null || v === ''
}

// isResolved reports whether a parameter needs no answer from the user:
// the schema supplies a default, or the workspace supplies exactly one
// candidate. Both mirror the CLI's resolution — defaults and
// single-candidate prefill apply without prompting — so the create forms
// can show only what a run would actually ask.
export function isResolved(f: TemplateField): boolean {
  return f.default !== undefined || f.suggestions?.length === 1
}

// resolvedValue is the value a bare run would use for a resolved field,
// with the workspace candidate the fresher fact of the two.
export function resolvedValue(f: TemplateField): unknown {
  if (f.suggestions?.length === 1) return f.suggestions[0]
  return f.default
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { TemplateField } from '../api'
import { isEmpty, isResolved, resolvedValue } from './form'

// useTemplateFields partitions a template's parameters the way the CLI's
// resolution treats them:
//
//   visible  — parameters a run would ask for: required, with no default
//              and no single workspace candidate.
//   optional — everything resolved without asking (defaults and
//              single-candidate prefill), plus optional parameters, kept
//              behind the advanced toggle for explicit override.
//
// values seeds every resolved parameter with the value a bare run would
// use, so submitting without touching the form equals the CLI's
// no-prompt path, and editing an advanced field mirrors --set.
export function useTemplateFields(fields: TemplateField[]) {
  const [values, setValues] = useState<Record<string, unknown>>(() => seed(fields))

  // Fields arrive asynchronously (the manifest fetch resolves after
  // mount), so seeding cannot stay a mount-time initializer. Merge new
  // seeds under existing values: a field the user already edited keeps
  // their input, everything else tracks the fetched manifest.
  const seededFor = useRef<TemplateField[]>(fields)
  useEffect(() => {
    if (seededFor.current === fields) return
    seededFor.current = fields
    setValues((prev) => ({ ...seed(fields), ...prev }))
  }, [fields])

  const visible = useMemo(
    () => fields.filter((f) => f.required && !isResolved(f)),
    [fields],
  )
  const optional = useMemo(
    () => fields.filter((f) => !(f.required && !isResolved(f))),
    [fields],
  )
  const missing = useMemo(
    () => visible.filter((f) => isEmpty(values[f.name])).map((f) => f.name),
    [visible, values],
  )
  const setValue = useCallback((key: string, v: unknown) => {
    setValues((prev) => ({ ...prev, [key]: v }))
  }, [])

  return { values, setValue, visible, optional, missing }
}

function seed(fields: TemplateField[]): Record<string, unknown> {
  const seeded: Record<string, unknown> = {}
  for (const f of fields) {
    if (isResolved(f)) seeded[f.name] = resolvedValue(f)
  }
  return seeded
}

package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// templatesProvider is the request-independent source for the template
// endpoints: the library release list, show and create all fetch and render
// against. Resolving it once per server keeps the release the form was filled
// against and the release the run renders from the same — a latest-release
// lookup per request could drift between the two.
type templatesProvider struct {
	version   string
	userAgent string

	// Test overrides; production leaves these zero-valued and gets the
	// official library.
	owner         string
	repo          string
	githubBaseURL string
}

// fetchLibrary resolves and downloads the provider's library release. The
// caller owns the returned Library and must Close it.
func (p templatesProvider) fetchLibrary(ctx context.Context) (*template.Library, error) {
	return template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       p.version,
		UserAgent:     p.userAgent,
		Owner:         p.owner,
		Repo:          p.repo,
		GitHubBaseURL: p.githubBaseURL,
	})
}

// createRequest is the POST /api/templates/{name}/create body.
type createRequest struct {
	// Name picks the output directory under the workspace root — the CLI's
	// --out-dir. It is deliberately decoupled from values.name, the schema
	// parameter: a template can want a PascalCase project name next to a
	// kebab-case directory, and the CLI separates the two the same way
	// (--set name=X --out-dir y). Required.
	Name string `json:"name"`

	// Dir is the root-relative, slash-separated directory the output renders
	// under; "" or "." is the workspace root — the pre-Dir behavior. It must
	// already exist: the endpoint scaffolds into systems, it does not invent
	// directory trees.
	Dir string `json:"dir,omitempty"`

	// Values are the template parameters, as --set would supply them.
	Values map[string]any `json:"values"`

	// Force allows rendering into a non-empty output directory.
	Force bool `json:"force,omitempty"`
}

// createResponse is the 201 payload: CreateResult with the output directory
// made root-relative, matching the identifier space /api/integrations uses.
type createResponse struct {
	*template.CreateResult
	// Diagnostics is what the render wrote to stderr, one entry per line —
	// the fetch notice and each dependency render. Provenance, not failure.
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// maxCreateBodyBytes caps a create request body. Parameter values are short
// scalars; a megabyte is already generous and keeps a malformed client from
// streaming unbounded input into memory.
const maxCreateBodyBytes = 1 << 20

// templateSummary is one list entry with the manifest metadata the create
// surfaces filter on — notably the intropy.dev/* labels a flow-view slot
// selects templates by. Additive beside the bare names `templates` keeps.
type templateSummary struct {
	Name        string            `json:"name"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
}

// listTemplates mirrors `template list -o json` against the server's library
// release, adding per-template metadata (`entries`) on top of the names. The
// describes are local reads on the already-extracted tarball; one malformed
// manifest drops that entry rather than hiding the rest of the library.
func (s *apiServer) listTemplates(w http.ResponseWriter, r *http.Request) {
	lib, err := s.templates.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	names, err := lib.List()
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	entries := make([]templateSummary, 0, len(names))
	for _, name := range names {
		desc, err := lib.Describe(name)
		if err != nil {
			continue
		}
		entries = append(entries, templateSummary{
			Name:        name,
			Title:       desc.Title,
			Description: desc.Description,
			Labels:      desc.Labels,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"owner":     lib.Owner,
		"repo":      lib.Repo,
		"version":   lib.Version,
		"templates": names,
		"entries":   entries,
	})
}

// getTemplate mirrors `template show -o json` for one template, adding the
// ordered field list the form renders from. The optional ?dir query names a
// root-relative directory the way createRequest.Dir does; when present, each
// field gains the parameter suggestions the workspace under it implies —
// the same candidates `int create` would prompt with there. Without it the
// response is context-free and suggestion-free.
func (s *apiServer) getTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	lib, err := s.templates.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	result, err := lib.Describe(name)
	if err != nil {
		writeError(w, templateFetchStatus(err), err.Error())
		return
	}

	if dir := r.URL.Query().Get("dir"); dir != "" {
		facts, err := s.factsForDir(dir)
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		suggestions := template.Suggest(result.Fields, facts, nil)
		for i := range result.Fields {
			result.Fields[i].Suggestions = suggestions[result.Fields[i].Name]
		}
	}
	writeJSON(w, http.StatusOK, result)
}

// factsForDir validates a root-relative dir with the create endpoint's
// rules and indexes the scaffold records under it. The dir must exist —
// suggesting from a system means the system directory is there.
func (s *apiServer) factsForDir(dir string) (*template.WorkspaceFacts, error) {
	segments, err := splitCreateDir(dir)
	if err != nil {
		return nil, err
	}
	abs := filepath.Join(append([]string{s.root}, segments...)...)
	if info, statErr := os.Stat(abs); statErr != nil || !info.IsDir() {
		return nil, fmt.Errorf("directory %q does not exist under the workspace root", dir)
	}
	facts, _ := system.LoadWorkspaceFacts(abs)
	return facts, nil
}

// createTemplate runs `int create` for one template: the form's values
// resolve non-interactively (a missing required parameter is a 422 naming
// it), the skeleton renders under the workspace root, and the result comes
// back as served. Runs are serialized: two concurrent renders of the same
// name would race on the output directory.
func (s *apiServer) createTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	var req createRequest
	dec := json.NewDecoder(io.LimitReader(r.Body, maxCreateBodyBytes))
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}

	outputDir, values, err := s.resolveCreate(req)
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	s.createMu.Lock()
	defer s.createMu.Unlock()

	prep, err := template.PrepareCreate(r.Context(), template.CreateOptions{
		Template:      name,
		Version:       s.templates.version,
		SetValues:     values,
		UserAgent:     s.templates.userAgent,
		Owner:         s.templates.owner,
		Repo:          s.templates.repo,
		GitHubBaseURL: s.templates.githubBaseURL,
	})
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	defer prep.Cleanup()

	var logs bytes.Buffer
	result, err := template.RunCreate(prep, outputDir, req.Force, &logs)
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	result.OutputDir = s.relPath(result.OutputDir)
	writeJSON(w, http.StatusCreated, createResponse{
		CreateResult: result,
		Diagnostics:  diagnosticLines(logs.String()),
	})
}

// resolveCreate folds the request into the output directory and value set
// `int create --name` would produce: name doubles as values.name and as the
// output directory under dir (the workspace root when dir is empty), confined
// there so the endpoint can never write outside the tree the dashboard serves.
func (s *apiServer) resolveCreate(req createRequest) (string, map[string]any, error) {
	if req.Name == "" {
		return "", nil, errors.New("name is required")
	}
	if strings.ContainsAny(req.Name, `/\`) || req.Name == "." || req.Name == ".." {
		return "", nil, fmt.Errorf("invalid name %q (must be a single path segment)", req.Name)
	}
	segments, err := splitCreateDir(req.Dir)
	if err != nil {
		return "", nil, err
	}

	values := req.Values
	if values == nil {
		values = map[string]any{}
	}
	// A template that does not declare `name` still gets the directory as
	// values.name — the CLI's --name sugar. When the template does declare
	// it, the form's value wins; the two are separate concerns.
	if _, ok := values["name"]; !ok {
		values["name"] = req.Name
	}
	for key := range values {
		if isReservedValueKey(key) {
			return "", nil, fmt.Errorf("value %q is reserved and cannot be supplied", key)
		}
	}

	rootAbs, err := filepath.Abs(s.root)
	if err != nil {
		return "", nil, err
	}
	parentDir := filepath.Join(append([]string{s.root}, segments...)...)
	if len(segments) > 0 {
		// The dir must already exist: creating into a system means the system
		// directory is there; anything else is a client mistake, not a mkdir.
		if info, statErr := os.Stat(parentDir); statErr != nil || !info.IsDir() {
			return "", nil, fmt.Errorf("directory %q does not exist under the workspace root", req.Dir)
		}
	}
	outputDir := filepath.Join(parentDir, req.Name)
	outAbs, err := filepath.Abs(outputDir)
	if err != nil {
		return "", nil, err
	}
	want := filepath.Join(append(append([]string{rootAbs}, segments...), req.Name)...)
	if outAbs != want {
		return "", nil, fmt.Errorf("invalid name %q (output would escape the workspace root)", req.Name)
	}
	return outputDir, values, nil
}

// splitCreateDir validates a create request's dir and returns its segments.
// "" and "." mean the workspace root (no segments). Each segment must be a
// plain directory name — no separators besides "/", no dot entries, nothing
// hidden — so the joined path can only descend from the root.
func splitCreateDir(dir string) ([]string, error) {
	if dir == "" || dir == "." {
		return nil, nil
	}
	if strings.Contains(dir, `\`) {
		return nil, fmt.Errorf("invalid dir %q (must be slash-separated)", dir)
	}
	segments := strings.Split(dir, "/")
	for _, seg := range segments {
		if seg == "" || seg == ".." || strings.HasPrefix(seg, ".") {
			return nil, fmt.Errorf("invalid dir %q (each segment must be a plain directory name)", dir)
		}
	}
	return segments, nil
}

// isReservedValueKey reports whether key is one of the reserved value keys a
// caller injects after resolution (topology, component, …). Users never
// supply them — a form value under one would collide with InjectReserved's
// refusal, so the endpoint refuses first with a message that says why.
func isReservedValueKey(key string) bool {
	switch key {
	case template.ReservedTopologyKey,
		template.ReservedComponentKey,
		template.ReservedGitopsKey,
		template.ReservedScaffoldKey,
		template.ReservedEnvKey:
		return true
	}
	return false
}

// templateFetchStatus maps a library fetch failure to the status the client
// can act on: an unknown template is a 404, anything upstream is a 502.
func templateFetchStatus(err error) int {
	if strings.Contains(err.Error(), "not found in") {
		return http.StatusNotFound
	}
	return http.StatusBadGateway
}

// createErrorStatus maps a create failure to the status the form renders:
// unmet parameters and name conflicts are 422 (the form highlights fields),
// a non-empty output directory is 409 (the form offers force), and a fetch
// failure is 502. Everything else is a plain 500.
func createErrorStatus(err error) int {
	msg := err.Error()
	switch {
	case strings.Contains(msg, "not empty"):
		return http.StatusConflict
	case strings.Contains(msg, "missing required parameter"),
		strings.Contains(msg, "unknown parameter"),
		strings.Contains(msg, "not found in"):
		return http.StatusUnprocessableEntity
	case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
		return http.StatusBadGateway
	}
	return http.StatusInternalServerError
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
  type TemplateSummary,
} from '../api'
import { Combobox } from './Combobox'
import { Field, FormField } from './form'
import { useTemplateFields } from './useTemplateFields'

/** The three create placeholders on the flow canvas, one per archetype
 *  column: in → process → out. */
export type SlotKind = 'extractor' | 'transactional' | 'loader'

// The intropy.dev/block-kind label value each slot filters templates by.
const KIND_BLOCK_LABEL: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'transactional-integration',
  loader: 'loader',
}

const KIND_TITLE: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'core block',
  loader: 'loader',
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'error'; message: string; status: number }

// norm compares label values the way dataFlowFor compares kinds: ignoring
// case and hyphens, so "transactional-integration" matches however the
// library spells it.
const norm = (s: string) => s.toLowerCase().replace(/-/g, '')

interface Props {
  kind: SlotKind
  /** Root-relative directory the new block scaffolds into ("." = workspace root). */
  systemPath: string
  systemLabel: string
  onClose: () => void
  /** Called with the created scaffold's root-relative path — the caller
   *  refreshes /api/flow so the new block appears as a ghost node. */
  onCreated: (outputDir: string) => void
}

// CreateDrawer is the flow view's create surface: opened by a placeholder
// slot, it offers the library's templates for that block kind and renders the
// selected one's manifest as the same form the templates view uses, scoped to
// the slot's system. Success is reported to the caller — the drawer closes
// and the canvas shows the new scaffold as a ghost node.
export function CreateDrawer({ kind, systemPath, systemLabel, onClose, onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [showAll, setShowAll] = useState(false)
  const [tpl, setTpl] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  const candidates = useMemo<TemplateSummary[]>(() => {
    if (!list) return []
    const entries: TemplateSummary[] =
      list.entries ?? list.templates.map((name) => ({ name }))
    if (showAll) return entries
    const want = norm(KIND_BLOCK_LABEL[kind])
    return entries.filter((e) => norm(e.labels?.['intropy.dev/block-kind'] ?? '') === want)
  }, [list, showAll, kind])

  // Keep the selection valid as the candidate list settles (load, show-all).
  useEffect(() => {
    setTpl((cur) =>
      cur && candidates.some((c) => c.name === cur) ? cur : candidates[0]?.name ?? null,
    )
  }, [candidates])

  return (
    <aside className="create-drawer">
      <header className="create-drawer-head">
        <div>
          <h2 className="create-drawer-title">New {KIND_TITLE[kind]}</h2>
          <span className="create-drawer-sys">in {systemLabel}</span>
        </div>
        <button type="button" className="flow-detail-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </header>

      {listError && <div className="banner error">{listError}</div>}
      {!list && !listError && <div className="empty">loading templates…</div>}

      {list && candidates.length === 0 && (
        <div className="empty">
          no template in {list.owner}/{list.repo}@{list.version} carries{' '}
          <code>intropy.dev/block-kind: {KIND_BLOCK_LABEL[kind]}</code>
          <div>
            <button type="button" className="flow-refresh" onClick={() => setShowAll(true)}>
              show all templates
            </button>
          </div>
        </div>
      )}

      {list && candidates.length > 0 && (
        <>
          <Field label="template" required>
            <Combobox
              value={tpl}
              options={candidates.map((c) => ({
                value: c.name,
                label: c.title ? `${c.title} (${c.name})` : c.name,
              }))}
              onChange={setTpl}
              placeholder="Select a template…"
            />
          </Field>
          {!showAll && (
            <button
              type="button"
              className="drawer-show-all"
              onClick={() => setShowAll(true)}
            >
              show all templates
            </button>
          )}
          {tpl && (
            <DrawerForm
              key={tpl}
              template={tpl}
              systemPath={systemPath}
              onCreated={onCreated}
            />
          )}
        </>
      )}
    </aside>
  )
}

// DrawerForm mirrors the templates view's TemplatePanel: manifest fetched,
// defaults seeded, required fields tracked, force offered on a 409. It is
// keyed by template name so switching templates resets all form state. The
// differences: the output directory is locked under the slot's system, and
// success closes the drawer instead of rendering a result card.
function DrawerForm({
  template,
  systemPath,
  onCreated,
}: {
  template: string
  systemPath: string
  onCreated: Props['onCreated']
}) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const { values, setValue, visible, optional, missing } = useTemplateFields(detail?.fields ?? [])
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [intName, setIntName] = useState('')
  const [force, setForce] = useState(false)
  const [create, setCreate] = useState<CreateState>({ phase: 'idle' })

  useEffect(() => {
    api
      .getTemplate(template, systemPath === '.' ? undefined : systemPath)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [template, systemPath])

  const run = useCallback(() => {
    setCreate({ phase: 'running' })
    api
      .createTemplate(template, { name: intName, dir: systemPath, values, force })
      .then((result: CreateResponse) => onCreated(result.outputDir))
      .catch((e: unknown) => {
        const err = e as { message?: string; status?: number }
        setCreate({ phase: 'error', message: errText(e), status: err.status ?? 0 })
      })
  }, [template, intName, systemPath, values, force, onCreated])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!detail) {
    return <div className="empty">loading {template}…</div>
  }

  const canRun = intName.trim() !== '' && missing.length === 0 && create.phase !== 'running'
  const prefix = systemPath === '.' ? '' : `${systemPath}/`

  return (
    <form
      className="template-form"
      onSubmit={(e) => {
        e.preventDefault()
        if (canRun) run()
      }}
    >
      {detail.description && <p className="template-desc">{detail.description}</p>}

      <Field
        label="out-dir"
        title="Output directory"
        description={
          prefix
            ? 'Scaffolded inside the system directory'
            : 'Scaffolded under the workspace root'
        }
        required
      >
        <div className="drawer-dir">
          {prefix && <span className="drawer-dir-prefix">{prefix}</span>}
          <input
            type="text"
            value={intName}
            onChange={(e) => setIntName(e.target.value)}
            placeholder="my-integration"
            autoFocus
          />
        </div>
      </Field>

      {visible.map((f) => (
        <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
      ))}

      {missing.length > 0 && (
        <div className="form-hint">missing required: {missing.join(', ')}</div>
      )}

      {optional.length > 0 && (
        <>
          <button
            type="button"
            className="advanced-toggle"
            onClick={() => setShowAdvanced((s) => !s)}
          >
            {showAdvanced ? '▾' : '▸'} advanced ({optional.length})
          </button>
          {showAdvanced &&
            optional.map((f) => (
              <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
            ))}
        </>
      )}

      {create.phase === 'error' && create.status === 409 && (
        <label className="force-row">
          <input type="checkbox" checked={force} onChange={(e) => setForce(e.target.checked)} />
          render into the non-empty directory anyway
        </label>
      )}

      <div className="form-actions">
        <button type="submit" className="run-btn" disabled={!canRun}>
          {create.phase === 'running' ? 'creating…' : 'int create'}
        </button>
      </div>

      {create.phase === 'error' && <div className="banner error">{create.message}</div>}
    </form>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

import { useCallback, useEffect, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
} from '../api'
import { Field, FormField } from './form'
import { useTemplateFields } from './useTemplateFields'

interface Props {
  /** Switch to the catalog with the newly created integration selected. */
  onCreated: (path: string) => void
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'done'; result: CreateResponse }
  | { phase: 'error'; message: string; status: number }

// TemplatesView is the `template` + `int create` surface: a list of the
// library's templates on the left, the selected one's manifest rendered as a
// form on the right, and a Run button that renders it into the workspace.
export function TemplatesView({ onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  // Auto-select the first template once the list loads.
  useEffect(() => {
    if (list && list.templates.length > 0 && !selected) {
      setSelected(list.templates[0])
    }
  }, [list, selected])

  if (listError) {
    return <div className="banner error">{listError}</div>
  }
  if (!list) {
    return <div className="empty">loading templates…</div>
  }
  if (list.templates.length === 0) {
    return (
      <div className="empty">
        no templates in {list.owner}/{list.repo}@{list.version}
      </div>
    )
  }

  return (
    <div className="templates-view">
      <aside className="templates-list">
        <div className="templates-list-head">
          <span className="sidebar-title">Templates</span>
          <span className="count">{list.templates.length}</span>
        </div>
        <div className="templates-lib">
          {list.owner}/{list.repo}@{list.version}
        </div>
        <ul>
          {list.templates.map((name) => (
            <li key={name}>
              <button
                className={`template-item${selected === name ? ' active' : ''}`}
                onClick={() => setSelected(name)}
                aria-current={selected === name ? 'page' : undefined}
              >
                {name}
              </button>
            </li>
          ))}
        </ul>
      </aside>
      <section className="templates-detail">
        {selected ? (
          <TemplatePanel key={selected} name={selected} onCreated={onCreated} />
        ) : (
          <div className="empty">select a template</div>
        )}
      </section>
    </div>
  )
}

// TemplatePanel renders one template's manifest as the create form. It is
// keyed by template name, so switching templates resets all form state.
function TemplatePanel({ name, onCreated }: { name: string; onCreated: Props['onCreated'] }) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const { values, setValue, visible, optional, missing } = useTemplateFields(detail?.fields ?? [])
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [intName, setIntName] = useState('')
  const [force, setForce] = useState(false)
  const [create, setCreate] = useState<CreateState>({ phase: 'idle' })

  useEffect(() => {
    api
      .getTemplate(name)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [name])

  const run = useCallback(() => {
    setCreate({ phase: 'running' })
    // name is the output directory (the CLI's --out-dir); values carries the
    // schema parameters, including the template's own `name` when declared.
    api
      .createTemplate(name, { name: intName, values, force })
      .then((result) => setCreate({ phase: 'done', result }))
      .catch((e: unknown) => {
        const err = e as { message?: string; status?: number }
        setCreate({ phase: 'error', message: errText(e), status: err.status ?? 0 })
      })
  }, [name, intName, values, force])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!detail) {
    return <div className="empty">loading {name}…</div>
  }

  const canRun = intName.trim() !== '' && missing.length === 0 && create.phase !== 'running'

  return (
    <div className="template-panel">
      <header className="template-head">
        <h2 className="template-title">{detail.title || detail.template}</h2>
        {detail.title && <span className="template-name">{detail.template}</span>}
        <span className="template-ref">
          {detail.owner}/{detail.repo}@{detail.version}
        </span>
      </header>
      {detail.description && <p className="template-desc">{detail.description}</p>}
      {detail.tags && detail.tags.length > 0 && (
        <div className="template-tags">
          {detail.tags.map((t) => (
            <span className="template-tag" key={t}>
              {t}
            </span>
          ))}
        </div>
      )}

      <div className="section-title">Parameters</div>
      <form
        className="template-form"
        onSubmit={(e) => {
          e.preventDefault()
          if (canRun) run()
        }}
      >
        <Field
          label="out-dir"
          title="Output directory"
          description="Where the integration is scaffolded, under the workspace root"
          required
        >
          <input
            type="text"
            value={intName}
            onChange={(e) => setIntName(e.target.value)}
            placeholder="my-integration"
            autoFocus
          />
        </Field>

        {visible.map((f) => (
          <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
        ))}

        {missing.length > 0 && (
          <div className="form-hint">missing required: {missing.join(', ')}</div>
        )}

        {optional.length > 0 && (
          <>
            <button
              type="button"
              className="advanced-toggle"
              onClick={() => setShowAdvanced((s) => !s)}
            >
              {showAdvanced ? '▾' : '▸'} advanced ({optional.length})
            </button>
            {showAdvanced &&
              optional.map((f) => (
                <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
              ))}
          </>
        )}

        {create.phase === 'error' && create.status === 409 && (
          <label className="force-row">
            <input type="checkbox" checked={force} onChange={(e) => setForce(e.target.checked)} />
            render into the non-empty directory anyway
          </label>
        )}

        <div className="form-actions">
          <button type="submit" className="run-btn" disabled={!canRun}>
            {create.phase === 'running' ? 'creating…' : 'int create'}
          </button>
        </div>
      </form>

      {create.phase === 'error' && (
        <div className="banner error">{create.message}</div>
      )}
      {create.phase === 'done' && (
        <div className="create-result">
          <div className="create-result-head">
            created <code>{create.result.outputDir}</code> from {create.result.owner}/
            {create.result.repo}@{create.result.version}
          </div>
          {create.result.dependencies && create.result.dependencies.length > 0 && (
            <ul className="create-deps">
              {create.result.dependencies.map((d) => (
                <li key={d.outputDir}>
                  {d.template} → {d.outputDir} <em>({d.action})</em>
                </li>
              ))}
            </ul>
          )}
          <button className="flow-refresh" onClick={() => onCreated(create.result.outputDir)}>
            view in catalog
          </button>
        </div>
      )}
    </div>
  )
}

function errText(e: unknown): string {
