// Package web embeds the Intropy dashboard SPA so the CLI can serve it
// without any runtime dependency on Node or a Vite dev server.
//
// Two trees are embedded and one is picked at serve time: placeholder/dist,
// committed, and dist, the `vite build` output (see `make web`), which is
// gitignored and present only in a workspace where the SPA has been built.
// go:embed patterns must match at compile time, so an unbuilt workspace
// keeps a marker file in dist (restored by `make web-clean`). A built dist
// drops the marker, and its absence is what makes the real SPA win — the
// state released binaries ship.
package web

import (
	"embed"
	"io/fs"
)

//go:embed all:placeholder/dist all:dist
var embedded embed.FS

package dashboard

import (
	"fmt"
	"io/fs"
	"net/http"
	"path"
	"strings"

	"github.com/integrio-intropy/intropy-cli/web"
)

// staticHandler serves the embedded SPA. Real build assets (hashed JS/CSS) are
// served with their correct content types; unknown *routes* fall back to
// index.html so the SPA's client-side routing works on deep links and reloads.
//
// A missing *file* (a path with an extension, e.g. /assets/index-abc123.js) is
// a 404 rather than a fallback. Serving index.html there would answer a script
// request with HTML and a 200, which the browser rejects on its MIME check and
// reports only as an empty page. A 404 names the missing file instead.
func staticHandler() (http.Handler, error) {
	index, err := fs.ReadFile(web.Assets, "index.html")
	if err != nil {
		// web.Assets always carries an index.html — the real build or the
		// committed placeholder — so this is unreachable by construction.
		return nil, fmt.Errorf("embedded dashboard is missing index.html: %w", err)
	}
	fileServer := http.FileServerFS(web.Assets)

	serveIndex := func(w http.ResponseWriter) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write(index)
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		name := path.Clean(strings.TrimPrefix(r.URL.Path, "/"))
		if name == "." || name == "" || name == "index.html" {
			serveIndex(w)
			return
		}
		if _, err := fs.Stat(web.Assets, name); err != nil {
			if path.Ext(name) != "" {
				http.NotFound(w, r)
				return
			}
			serveIndex(w)
			return
		}
		fileServer.ServeHTTP(w, r)
	}), nil
}

